6	/// GPX 1.1 最小读写：抽 trkpt/rtept，写 rte 或 trk。
7	abstract class GpxUtil {
8	  static final _ptRe = RegExp(
9	    r'<(?:trkpt|rtept)\s+[^>]*lat="([+-]?\d+(?:\.\d+)?)"[^>]*lon="([+-]?\d+(?:\.\d+)?)"',
10	    caseSensitive: false,
11	  );
