13	  static final _ptReSwap = RegExp(
14	    r'<(?:trkpt|rtept)\s+[^>]*lon="([+-]?\d+(?:\.\d+)?)"[^>]*lat="([+-]?\d+(?:\.\d+)?)"',
15	    caseSensitive: false,
16	  );
17	
18	  static final _nameRe = RegExp(
19	    r'<name>\s*([^<]+)\s*</name>',
20	    caseSensitive: false,
21	  );
22	
23	  static final _timeRe = RegExp(
24	    r'<time>\s*([^<]+)\s*</time>',
25	    caseSensitive: false,
26	  );
27	
28	  static final _trkptRe = RegExp(
29	    r'<trkpt\b([^>]*)>([\s\S]*?)</trkpt>',
30	    caseSensitive: false,
31	  );
32	
33	  static final _trkptSelfRe = RegExp(
34	    r'<trkpt\b([^>]*)\s*/>',
35	    caseSensitive: false,
36	  );
37	
38	  static final _metaOpenRe = RegExp(r'<metadata\b[^>]*>', caseSensitive: false);
39	
40	  static final _gpxOpenRe = RegExp(r'<gpx\b[^>]*>', caseSensitive: false);
