93	  /// 解析名称、点列、以及文件内可信的起止时间。
94	  static GpxSummary parse(String xml) {
95	    var name = '';
96	    final m = _nameRe.firstMatch(xml);
97	    if (m != null) {
98	      name = m.group(1)!.trim();
99	    }
100	
101	    final raw = _extractPts(xml);
102	    final points = [for (final p in raw) p.ll];
103	    final km = distanceKm(points);
104	    final times = plausibleTimes(xml);
105	    final start = times.isEmpty ? null : times.first;
106	    final end = times.isEmpty ? null : times.last;
107	    Duration? duration;
108	    if (start != null && end != null) {
109	      final d = end.difference(start);
110	      if (d.inSeconds >= 15) duration = d;
111	    }
112	    final speeds = _speedSeries(raw);
113	    final hr = _hrSeries(raw);
114	    final elev = _elev(raw);
115	    var gain = elev.gain;
116	    final extClimb = _extClimbRe.firstMatch(xml);
117	    if (gain == null && extClimb != null) {
118	      final v = double.tryParse(extClimb.group(1)!);
119	      if (v != null && v > 0.5) gain = v;
120	    }
121	    double? avg;
122	    if (duration != null && km > 0.05) {
123	      final hours = duration.inMilliseconds / 3600000.0;
124	      if (hours > 0) avg = km / hours;
125	    }
126	    if (avg == null && speeds.points.isNotEmpty) {
127	      var s = 0.0;
128	      for (final p in speeds.points) {
129	        s += p.value;
130	      }
131	      avg = s / speeds.points.length;
132	    }
133	    var atPoint = speeds.atPoint;
134	    if (avg != null && avg > 0 && atPoint.length > 1) {
135	      var any = false;
136	      for (final v in atPoint) {
137	        if (v > 0.2) {
138	          any = true;
139	          break;
140	        }
141	      }
142	      if (!any) {
143	        atPoint = List<double>.filled(atPoint.length, avg);
144	        atPoint[0] = 0;
145	      }
146	    }
147	    return GpxSummary(
148	      name: name,
149	      points: points,
150	      distanceKm: km,
151	      startTime: start,
152	      endTime: end,
153	      duration: duration,
154	      avgSpeedKmh: avg,
155	      maxSpeedKmh: speeds.max,
156	      elevGainM: gain,
157	      elevLossM: elev.loss,
158	      minEleM: elev.min,
159	      maxEleM: elev.max,
160	      avgHrBpm: hr.avg,
161	      maxHrBpm: hr.max,
162	      hrPoints: hr.points,
163	      speedPoints: speeds.points,
164	      pointSpeedsKmh: speeds.atPoint,
165	    );
166	  }
