168	  static List<_GpxPt> _extractPts(String xml) {
169	    final out = <_GpxPt>[];
170	    for (final match in _openPtRe.allMatches(xml)) {
171	      final ll = _llFromAttrs(match.group(1)!);
172	      if (ll == null) continue;
173	      final inner = match.group(2)!;
174	      final eleM = _eleRe.firstMatch(inner);
175	      final timeM = _timeRe.firstMatch(inner);
176	      DateTime? t;
177	      if (timeM != null) {
178	        t = tryParseUtc(timeM.group(1)!);
179	        if (t != null && !isPlausibleTime(t)) t = null;
180	      }
181	      out.add((
182	        ll: ll,
183	        ele: eleM == null ? null : double.tryParse(eleM.group(1)!),
184	        time: t,
185	        hr: _hrFromInner(inner),
186	      ));
187	    }
188	    if (out.isNotEmpty) return out;
189	    for (final match in _ptRe.allMatches(xml)) {
190	      final lat = double.tryParse(match.group(1)!);
191	      final lon = double.tryParse(match.group(2)!);
192	      if (lat != null && lon != null) {
193	        out.add((ll: LatLng(lat, lon), ele: null, time: null, hr: null));
194	      }
195	    }
196	    if (out.isNotEmpty) return out;
197	    for (final match in _ptReSwap.allMatches(xml)) {
198	      final lon = double.tryParse(match.group(1)!);
199	      final lat = double.tryParse(match.group(2)!);
200	      if (lat != null && lon != null) {
201	        out.add((ll: LatLng(lat, lon), ele: null, time: null, hr: null));
202	      }
203	    }
204	    return out;
205	  }
