207	  static int? _hrFromInner(String inner) {
208	    final m = _hrRe.firstMatch(inner);
209	    if (m == null) return null;
210	    final v = int.tryParse(m.group(1)!);
211	    if (v == null || v < _hrMinBpm || v > _hrMaxBpm) return null;
212	    return v;
213	  }
