254	  /// 沿轨迹每整公里一个点。
255	  ///
256	  /// [at] 是它落在轨迹上的位置，用「点下标」表示（`4.5` = 第 4、5 点之间）。回放时
257	  /// 用它判断线画到没有 —— 缺了它就只能猜，牌子要么全出来要么全不出来。
258	  static List<({LatLng ll, int km, double at})> kmMarkers(
259	    List<LatLng> points, {
260	    double intervalKm = 1,
261	    int maxMarks = 120,
262	  }) {
263	    final out = <({LatLng ll, int km, double at})>[];
264	    if (points.length < 2 || intervalKm <= 0) return out;
265	    var acc = 0.0;
266	    var next = intervalKm;
267	    var n = 1;
268	    for (var i = 1; i < points.length; i++) {
269	      final d = _haversineKm(points[i - 1], points[i]);
270	      if (d <= 0) continue;
271	      while (acc + d >= next && n <= maxMarks) {
272	        final t = ((next - acc) / d).clamp(0.0, 1.0);
273	        final a = points[i - 1];
274	        final b = points[i];
275	        out.add((
276	          ll: LatLng(
277	            a.latitude + (b.latitude - a.latitude) * t,
278	            a.longitude + (b.longitude - a.longitude) * t,
279	          ),
280	          km: n,
281	          at: (i - 1) + t,
282	        ));
283	        n++;
284	        next += intervalKm;
285	      }
286	      acc += d;
287	    }
288	    return out;
289	  }
