291	  /// 每个点的累计骑行时间（秒，从 0 起）。
292	  ///
293	  /// 用相邻两点的距离除以该点速度累加，还原「这段路实际花了多久」，回放时才能
294	  /// 按运动本身的速度推进（快的地方画得快）。比按点数平均更贴近真实节奏。
295	  /// 速度缺失或异常（<=0.2 km/h）时用 [fallbackKmh] 兜底。
296	  static List<double> cumulativeRideSeconds(
297	    List<LatLng> points,
298	    List<double> speedsAtPoint, {
299	    double fallbackKmh = 18,
300	  }) {
301	    final n = points.length;
302	    final out = List<double>.filled(n, 0);
303	    if (n < 2) return out;
304	    var acc = 0.0;
305	    for (var i = 1; i < n; i++) {
306	      final d = _haversineKm(points[i - 1], points[i]);
307	      var v = i < speedsAtPoint.length ? speedsAtPoint[i] : fallbackKmh;
308	      if (!(v > 0.2)) v = fallbackKmh;
309	      acc += d / v * 3600.0;
310	      out[i] = acc;
311	    }
312	    return out;
313	  }
