315	  static ({int? avg, int? max, List<RideSeriesPoint> points}) _hrSeries(
316	    List<_GpxPt> pts,
317	  ) {
318	    final series = <RideSeriesPoint>[];
319	    var sum = 0;
320	    var maxV = 0;
321	    for (final p in pts) {
322	      final hr = p.hr;
323	      if (hr == null) continue;
324	      series.add(RideSeriesPoint(time: p.time, value: hr.toDouble()));
325	      sum += hr;
326	      if (hr > maxV) maxV = hr;
327	    }
328	    if (series.isEmpty) {
329	      return (avg: null, max: null, points: const []);
330	    }
331	    return (
332	      avg: (sum / series.length).round(),
333	      max: maxV,
334	      points: series,
335	    );
336	  }
