338	  static ({double? gain, double? loss, double? min, double? max}) _elev(
339	    List<_GpxPt> pts,
340	  ) {
341	    double? minV;
342	    double? maxV;
343	    var gain = 0.0;
344	    var loss = 0.0;
345	    double? prev;
346	    var n = 0;
347	    for (final p in pts) {
348	      final e = p.ele;
349	      if (e == null) continue;
350	      n++;
351	      minV = minV == null ? e : math.min(minV, e);
352	      maxV = maxV == null ? e : math.max(maxV, e);
353	      if (prev != null) {
354	        final d = e - prev;
355	        if (d > 0.8) gain += d;
356	        if (d < -0.8) loss += -d;
357	      }
358	      prev = e;
359	    }
360	    if (n < 2) {
361	      return (gain: null, loss: null, min: minV, max: maxV);
362	    }
363	    return (
364	      gain: gain > 0.5 ? gain : null,
365	      loss: loss > 0.5 ? loss : null,
366	      min: minV,
367	      max: maxV,
368	    );
369	  }
