396	  /// 心率区间累计（热身 / 燃脂 / 有氧 / 无氧 / 极限）。
397	  static List<Duration> hrZoneDurations(
398	    List<RideSeriesPoint> pts, {
399	    Duration? total,
400	  }) {
401	    final zones = List<Duration>.filled(5, Duration.zero);
402	    if (pts.isEmpty) return zones;
403	    final fallbackMs =
404	        (total?.inMilliseconds ?? pts.length * 1000) ~/ pts.length;
405	    for (var i = 0; i < pts.length; i++) {
406	      var ms = fallbackMs;
407	      if (i + 1 < pts.length) {
408	        final a = pts[i].time;
409	        final b = pts[i + 1].time;
410	        if (a != null && b != null) {
411	          final d = b.difference(a).inMilliseconds;
412	          if (d > 0 && d <= 120000) ms = d;
413	        }
414	      }
415	      if (ms <= 0) continue;
416	      final z = hrZoneIndex(pts[i].value.round());
417	      zones[z] += Duration(milliseconds: ms);
418	    }
419	    return zones;
420	  }
