422	  /// 按默认最大心率 190 的五区。
423	  static int hrZoneIndex(int bpm) {
424	    if (bpm < 114) return 0;
425	    if (bpm < 133) return 1;
426	    if (bpm < 152) return 2;
427	    if (bpm < 171) return 3;
428	    return 4;
429	  }
