431	  /// 无热量字段时的估算：有心率用 Keytel 简化，否则按里程。
432	  static int estimateKcal({
433	    int? avgHrBpm,
434	    Duration? duration,
435	    double distanceKm = 0,
436	  }) {
437	    final minutes = (duration?.inSeconds ?? 0) / 60.0;
438	    if (avgHrBpm != null && avgHrBpm > 0 && minutes > 0) {
439	      return math.max(1, (avgHrBpm * minutes * 0.03).round());
440	    }
441	    if (distanceKm > 0.001) {
442	      return math.max(1, (distanceKm * 30).round());
443	    }
444	    return 0;
445	  }
