447	  /// 文件里按出现顺序的可信 UTC 时间（忽略码表未校时的 1970/2000）。
448	  static List<DateTime> plausibleTimes(String xml) {
449	    final out = <DateTime>[];
450	    for (final match in _timeRe.allMatches(xml)) {
451	      final t = tryParseUtc(match.group(1)!);
452	      if (t != null && isPlausibleTime(t)) {
