468	  /// GNSS / 手机时间：2020 年之后、且不超过「现在 + 2 天」。
469	  static bool isPlausibleTime(DateTime t) {
470	    final u = t.toUtc();
471	    final now = DateTime.now().toUtc();
472	    return u.year >= 2020 && !u.isAfter(now.add(const Duration(days: 2)));
473	  }
