487	  /// 相邻点球面距离之和，千米。
488	  static double distanceKm(List<LatLng> points) {
489	    var sum = 0.0;
490	    for (var i = 1; i < points.length; i++) {
491	      sum += _haversineKm(points[i - 1], points[i]);
492	    }
493	    return sum;
494	  }
495	
496	  static double _haversineKm(LatLng a, LatLng b) {
497	    const r = 6371.0;
498	    final dLat = _rad(b.latitude - a.latitude);
499	    final dLon = _rad(b.longitude - a.longitude);
500	    final x = math.sin(dLat / 2) * math.sin(dLat / 2) +
501	        math.cos(_rad(a.latitude)) *
502	            math.cos(_rad(b.latitude)) *
503	            math.sin(dLon / 2) *
504	            math.sin(dLon / 2);
505	    return 2 * r * math.asin(math.min(1, math.sqrt(x)));
506	  }
507	
508	  static double _rad(double deg) => deg * math.pi / 180;
