510	  /// 列表缩略图用：保留起终点，中间均匀抽点。
511	  static List<LatLng> previewTrack(List<LatLng> points, {int max = 48}) {
512	    if (points.length <= 2) return List<LatLng>.from(points);
513	    if (points.length <= max) return List<LatLng>.from(points);
514	    final last = points.length - 1;
515	    final out = <LatLng>[];
516	    for (var i = 0; i < max; i++) {
517	      final idx = ((last * i) / (max - 1)).round();
518	      if (out.isEmpty || out.last != points[idx]) {
519	        out.add(points[idx]);
520	      }
521	    }
522	    if (out.last != points.last) out.add(points.last);
523	    return out;
524	  }
