526	  /// 稀疏途经点：route。写入 metadata 时间（手机时钟）。
527	  static String writeRoute({
528	    required String name,
529	    required List<LatLng> points,
530	    List<String>? labels,
531	    DateTime? timeUtc,
532	  }) {
533	    final metaTime = formatUtc(timeUtc ?? DateTime.now().toUtc());
534	    final buf = StringBuffer()
535	      ..writeln('<?xml version="1.0" encoding="UTF-8"?>')
536	      ..writeln(
537	        '<gpx version="1.1" creator="Helm One App" '
538	        'xmlns="http://www.topografix.com/GPX/1/1">',
539	      )
540	      ..writeln(
541	        '  <metadata><name>${_esc(name)}</name>'
542	        '<time>$metaTime</time></metadata>',
543	      )
544	      ..writeln('  <rte>')
