  /// 逐点速度。优先用码表记录的设备速度（m/s → km/h），没有才用相邻点
  /// 距离 / 时间差推算；都缺失时沿用上一个值（第 0 点为 0）。
  static ({double? max, List<RideSeriesPoint> points, List<double> atPoint})
      _speedSeries(List<_GpxPt> pts) {
    var maxV = 0.0;
    final series = <RideSeriesPoint>[];
    final atPoint = List<double>.filled(pts.length, 0);
    var last = 0.0;
    for (var i = 0; i < pts.length; i++) {
      var v = last;
      final dev = pts[i].spdMps;
      if (dev != null) {
        // 设备速度哪怕时间差不在 0.8~60 s 里也算数（GNSS 可能丢点）。
        v = dev * 3.6;
        series.add(RideSeriesPoint(time: pts[i].time, value: v));
        if (v > maxV) maxV = v;
      } else if (i > 0) {
        final a = pts[i - 1].time;
        final b = pts[i].time;
        if (a != null && b != null) {
          final sec = b.difference(a).inMilliseconds / 1000.0;
          if (sec >= 0.8 && sec <= 60) {
            final km = _haversineKm(pts[i - 1].ll, pts[i].ll);
            final raw = km / (sec / 3600.0);
            if (raw > 0 && raw < 80) {
              v = raw;
              series.add(RideSeriesPoint(time: b, value: v));
              if (v > maxV) maxV = v;
            }
          }
        }
      }
      atPoint[i] = v;
      last = v;
    }
    return (
      max: maxV > 0.5 ? maxV : null,
      points: series,
      atPoint: atPoint,
    );
  }
