207	  static List<_GpxPt> _extractPts(String xml) {
208	    final out = <_GpxPt>[];
209	    for (final match in _openPtRe.allMatches(xml)) {
210	      final ll = _llFromAttrs(match.group(1)!);
211	      if (ll == null) continue;
212	      final inner = match.group(2)!;
213	      final eleM = _eleRe.firstMatch(inner);
214	      final timeM = _timeRe.firstMatch(inner);
215	      DateTime? t;
216	      if (timeM != null) {
217	        t = tryParseUtc(timeM.group(1)!);
218	        if (t != null && !isPlausibleTime(t)) t = null;
219	      }
220	      out.add((
221	        ll: ll,
222	        ele: eleM == null ? null : double.tryParse(eleM.group(1)!),
223	        time: t,
224	        hr: _hrFromInner(inner),
225	        cad: _cadFromInner(inner),
226	        pw: _powerFromInner(inner),
227	        spdMps: _speedFromInner(inner),
228	      ));
229	    }

