304	  /// 逐点速度。优先用码表记录的设备速度（m/s → km/h），没有才用相邻点
305	  /// 距离 / 时间差推算；都缺时沿用上一个值（第 0 点为 0）。
306	  static ({double? max, List<RideSeriesPoint> points, List<double> atPoint})
307	      _speedSeries(List<_GpxPt> pts) {
308	    var maxV = 0.0;
309	    final series = <RideSeriesPoint>[];
310	    final atPoint = List<double>.filled(pts.length, 0);
311	    var last = 0.0;
312	    for (var i = 0; i < pts.length; i++) {
313	      var v = last;
314	      final dev = pts[i].spdMps;
315	      if (dev != null) {
316	        // 设备速度不受 0.8~60 s 时间窗限制（GNSS 丢点时照样可信）。
317	        v = dev * 3.6;
318	        series.add(RideSeriesPoint(time: pts[i].time, value: v));
319	        if (v > maxV) maxV = v;
320	      } else if (i > 0) {
321	        final a = pts[i - 1].time;
322	        final b = pts[i].time;
323	        if (a != null && b != null) {
324	          final sec = b.difference(a).inMilliseconds / 1000.0;
325	          if (sec >= 0.8 && sec <= 60) {
326	            final km = _haversineKm(pts[i - 1].ll, pts[i].ll);
327	            final raw = km / (sec / 3600.0);
328	            if (raw > 0 && raw < 80) {
329	              v = raw;
330	              series.add(RideSeriesPoint(time: b, value: v));
331	              if (v > maxV) maxV = v;
332	            }
333	          }
334	        }
335	      }
336	      atPoint[i] = v;
337	      last = v;
338	    }
339	    return (
340	      max: maxV > 0.5 ? maxV : null,
341	      points: series,
342	      atPoint: atPoint,
343	    );
344	  }
